public class ThreadingComparison {
    // PERFECT FOR VIRTUAL THREADS: I/O Bound
    public void handleIoBoundWork(List<String> urls) {
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (String url : urls) {
                executor.submit(() -> {
                    // Blocking network call unmounts the virtual thread automatically
                    return fetchRemoteData(url);
                });
            }
        }
    }

    // WRONG FOR VIRTUAL THREADS: CPU Bound
    public void handleCpuBoundWork(List<byte[]> payloads) {
        // Use a fixed pool matching core count instead of virtual threads
        int cores = Runtime.getRuntime().availableProcessors();
        try (var executor = Executors.newFixedThreadPool(cores)) {
            for (byte[] payload : payloads) {
                executor.submit(() -> {
                    // Heavy cryptographic computation saturating the CPU core
                    return computeExpensiveHash(payload);
                });
            }
        }
    }

    private native String fetchRemoteData(String url); 
    private native byte[] computeExpensiveHash(byte[] payload);
}
